import { useState, type CSSProperties, type ReactNode } from "react";
import { KeyValueList } from "@/shared/ui/data/KeyValueList";
import { PageHeader } from "@/shared/ui/pages/pageHeader";
import { MasterDetail } from "@/shared/ui/layouts/MasterDetail";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";
import { IconButton } from "@/shared/ui/controls/IconButton";
import { Text } from "@/shared/ui/typography/Text";
import { Stack } from "@/shared/ui/layout/Stack";

const ELLIPSIS: CSSProperties = { overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" };

export interface TreeNodeData { id: string; label: string; meta?: string; children?: TreeNodeData[]; }
function flattenTree(nodes: TreeNodeData[]): { node: TreeNodeData }[] {
  const out: { node: TreeNodeData }[] = [];
  const walk = (list: TreeNodeData[]) => { for (const n of list) { out.push({ node: n }); if (n.children) walk(n.children); } };
  walk(nodes);
  return out;
}
function Tree({ nodes, selectedId, defaultSelectedId, onSelect, detail, toolbar, defaultCollapsedIds, indent = 16, railWidth = 260, loading = false }: {
  nodes: TreeNodeData[]; selectedId?: string | null; defaultSelectedId?: string; onSelect?: (id: string) => void;
  detail?: ReactNode | ((node: TreeNodeData | undefined) => ReactNode); toolbar?: ReactNode; defaultCollapsedIds?: string[]; indent?: number; railWidth?: number; loading?: boolean;
}) {
  const [innerSelected, setInnerSelected] = useState<string | null>(defaultSelectedId ?? null);
  const [collapsed, setCollapsed] = useState<ReadonlySet<string>>(() => new Set(defaultCollapsedIds));
  if (loading) {
    return (
      <MasterDetail toolbar={toolbar} railWidth={railWidth}
        rail={<Stack gap={6}>{Array.from({ length: 6 }).map((_, i) => <Skeleton key={i} h={20} radius={5} w={i % 3 === 0 ? "70%" : "100%"} style={{ marginLeft: i % 3 === 1 ? 16 : 0 }} />)}</Stack>}
        detail={<Stack gap={10}><Skeleton w="40%" h={16} /><Skeleton w="90%" h={11} /><Skeleton w="70%" h={11} /></Stack>}
      />
    );
  }
  const controlled = selectedId !== undefined;
  const selected = controlled ? selectedId : innerSelected;
  const select = (id: string) => { if (!controlled) setInnerSelected(id); onSelect?.(id); };
  const toggle = (id: string) => { const next = new Set(collapsed); if (next.has(id)) next.delete(id); else next.add(id); setCollapsed(next); };
  const flat = flattenTree(nodes);
  const selectedNode = flat.find((f) => f.node.id === selected)?.node;
  const detailNode = typeof detail === "function" ? detail(selectedNode) : detail;
  const rows = (list: readonly TreeNodeData[], depth: number): ReactNode[] =>
    list.flatMap((n) => {
      const branch = !!n.children?.length;
      const isCollapsed = collapsed.has(n.id);
      const isSelected = selected === n.id;
      const row = (
        <div key={n.id} role="treeitem" aria-selected={isSelected} tabIndex={0} onClick={() => select(n.id)}
          style={{ display: "flex", alignItems: "center", gap: 4, padding: "4px 8px", paddingLeft: 6 + depth * indent, borderRadius: 6, cursor: "pointer", background: isSelected ? "var(--accent-soft)" : "transparent", border: `1px solid ${isSelected ? "var(--accent-dim)" : "transparent"}` }}>
          {branch ? (
            <IconButton aria-label={`${isCollapsed ? "expand" : "collapse"} ${n.label}`} onClick={(e: any) => { e.stopPropagation(); toggle(n.id); }}>
              <span style={{ display: "inline-block", fontSize: 9, color: "var(--fg-muted)", transition: "transform .12s ease", transform: isCollapsed ? "none" : "rotate(90deg)" }}>{">"}</span>
            </IconButton>
          ) : <span style={{ display: "inline-block", width: 16, flex: "none" }} />}
          <span style={{ fontSize: 12, minWidth: 0, ...ELLIPSIS }}>{n.label}</span>
          {n.meta && <span style={{ fontSize: 10, color: "var(--fg-dim)", fontFamily: "var(--mono)", marginLeft: "auto", flex: "none" }}>{n.meta}</span>}
        </div>
      );
      return branch && !isCollapsed ? [row, ...rows(n.children as TreeNodeData[], depth + 1)] : [row];
    });
  return (
    <MasterDetail toolbar={toolbar} railWidth={railWidth}
      rail={<div role="tree" style={{ display: "flex", flexDirection: "column", gap: 2 }}>{rows(nodes, 0)}</div>}
      detail={detailNode ?? null} />
  );
}

export interface TreeExplorerPageProps {
  title?: ReactNode;
  hint?: ReactNode;
  toolbar?: ReactNode;
  nodes?: TreeNodeData[];
  selectedId?: string | null;
  defaultSelectedId?: string;
  onSelect?: (id: string) => void;
  defaultCollapsedIds?: string[];
  detail?: (node: TreeNodeData) => ReactNode;
  nodeFacts?: (node: TreeNodeData) => { k: ReactNode; v: ReactNode }[];
  railWidth?: number;
  className?: string;
  loading?: boolean;
}
const DEMO_NODES: TreeNodeData[] = [
  {
    id: "src", label: "src", meta: "dir",
    children: [
      { id: "app", label: "app", children: [{ id: "main", label: "main.tsx" }] },
      { id: "shared", label: "shared" },
    ],
  },
];
export function TreeExplorerPage({
  title = "Files", hint = "src/", toolbar,
  nodes = DEMO_NODES,
  selectedId, defaultSelectedId = "src", onSelect,
  defaultCollapsedIds,
  detail, nodeFacts, railWidth = 260, className, loading = false,
}: TreeExplorerPageProps) {
  const defaultDetail = (node: TreeNodeData): ReactNode => (
    <Stack gap={12}>
      <Text size="md" weight={600}>{node.label}</Text>
      <KeyValueList mono items={[
        { k: "id", v: node.id },
        ...(node.meta != null ? [{ k: "meta", v: node.meta }] : []),
        { k: "children", v: `${node.children?.length ?? 0}` },
        ...(nodeFacts?.(node) ?? []),
      ]} />
    </Stack>
  );

  return (
    <Tree
      nodes={nodes}
      selectedId={selectedId}
      defaultSelectedId={defaultSelectedId}
      onSelect={onSelect}
      defaultCollapsedIds={defaultCollapsedIds}
      railWidth={railWidth}
      loading={loading}
      toolbar={<PageHeader title={title} hint={hint} toolbar={toolbar} />}
      detail={(node) =>
        node ? (detail?.(node) ?? defaultDetail(node)) : (
          <EmptyState title="No node selected" description="Select a node in the tree to inspect it." />
        )
      }
    />
  );
}

